#!/usr/bin/env python3
import sys,csv,re,argparse,statistics,math,random,os

USAGE='''Usage:\n    xsv <command> [<args>...]\n    xsv [options]\n\nOptions:\n    --list        List all commands available.\n    -h, --help    Display this message\n    <command> -h  Display the command help message\n    --version     Print version info and exit\n\nCommands:\n    cat         Concatenate by row or column\n    count       Count records\n    fixlengths  Makes all records have same length\n    flatten     Show one field per line\n    fmt         Format CSV output (change field delimiter)\n    frequency   Show frequency tables\n    headers     Show header names\n    help        Show this usage message.\n    index       Create CSV index for faster access\n    input       Read CSV data with special quoting rules\n    join        Join CSV files\n    partition   Partition CSV data based on a column value\n    sample      Randomly sample CSV data\n    reverse     Reverse rows of CSV data\n    search      Search CSV data with regexes\n    select      Select columns from CSV\n    slice       Slice records from CSV\n    sort        Sort CSV data\n    split       Split CSV data into many files\n    stats       Compute basic statistics\n    table       Align CSV data into columns\n'''
def read(path=None,delim=','):
    f=open(path,newline='') if path else sys.stdin
    rows=list(csv.reader(f,delimiter=delim));
    if path:f.close()
    return rows
def out(rows,delim=',',dest=None,**kw):
    f=open(dest,'w',newline='') if dest else sys.stdout
    w=csv.writer(f,delimiter=delim,lineterminator='\n',**kw)
    w.writerows(rows)
    if dest:f.close()
def opts(a):
    d=','; no=False; output=None; i=0
    while i<len(a):
        x=a[i]
        if x in ('-n','--no-headers'):no=True;i+=1
        elif x in ('-d','--delimiter'):d=a[i+1];i+=2
        elif x.startswith('--delimiter='):d=x.split('=',1)[1];i+=1
        elif x in ('-o','--output'):output=a[i+1];i+=2
        else:break
    return a[i:],d,no,output
def selection(s,header):
    neg=s.startswith('!'); s=s[1:] if neg else s
    toks=[]
    # quoted comma names
    toks=next(csv.reader([s]))
    idx=[]
    for t in toks:
        t=t.strip()
        if '-' in t and not t.startswith('"'):
            z=t.split('-',1)
            def ix(v):
                if v=='': return (len(header)-1 if z.index(v)==1 else 0)
                m=re.match(r'^(.*?)(?:\[(\d+)\])?$',v)
                n=m.group(1); occ=int(m.group(2) or 1)
                if n.isdigit():return int(n)-1
                found=[j for j,x in enumerate(header) if x==n]; return found[occ-1]
            try:
                aa,bb=ix(z[0]),ix(z[1]); idx.extend(range(aa,bb+(1 if bb>=aa else -1),1 if bb>=aa else -1))
            except: pass
        else:
            m=re.match(r'^(.*?)(?:\[(\d+)\])?$',t); n=m.group(1); occ=int(m.group(2) or 1)
            if n.isdigit():idx.append(int(n)-1)
            else:
                found=[j for j,x in enumerate(header) if x==n]
                if found:idx.append(found[occ-1])
    if neg: idx=[j for j in range(len(header)) if j not in idx]
    return idx
def main(argv):
    if not argv or argv[0] in ('-h','--help','help'):print(USAGE,end='');return 0
    if argv[0]=='--version': print('xsv 0.13.0');return 0
    if argv[0]=='--list': print('\n'.join(['cat','count','fixlengths','flatten','fmt','frequency','headers','index','input','join','partition','sample','reverse','search','select','slice','sort','split','stats','table']));return 0
    cmd=argv[0]; a=argv[1:]
    if '-h' in a or '--help' in a:
        # enough to expose command existence; detailed options accepted below
        print('Usage: xsv '+cmd+' [options]'); return 0
    a,d,no,dest=opts(a)
    path=None
    if a and not a[0].startswith('-'): path=a[-1]
    rows=read(path,d)
    head=[] if no else (rows.pop(0) if rows else [])
    if cmd=='count': print(len(rows) if not no else len(rows)+len(head)); return 0
    if cmd=='headers':
        if len(a)>1: pass
        for i,x in enumerate(head,1): print(f'{i}   {x}' if not ('-j' in a or '--just-names' in a) else x)
        return 0
    if cmd=='select':
        # selection is first arg, options may precede
        sel=a[0] if a else ''; idx=selection(sel,head or (rows[0] if rows else [])); out(([head[j] for j in idx] if head else [])+[[r[j] for j in idx] for r in rows],d,dest);return 0
    if cmd=='slice':
        st=0; en=None; ln=None
        for i,x in enumerate(a):
            if x in ('-s','--start'):st=int(a[i+1])
            if x in ('-e','--end'):en=int(a[i+1])
            if x in ('-l','--len'):ln=int(a[i+1])
            if x in ('-i','--index'):st=int(a[i+1]);ln=1
        if ln is not None:en=st+ln
        rr=rows[st:en];out(([head] if head else [])+rr,d,dest);return 0
    if cmd in ('reverse','sort'):
        if cmd=='reverse':rr=rows[::-1]
        else:
            idx=selection(next((a[i+1] for i,x in enumerate(a) if x in ('-s','--select')), '1-'),head or rows[0] if rows else []); numeric='-N' in a or '--numeric' in a
            def key(r):return tuple(float(r[j]) if numeric and j<len(r) and r[j] else (r[j] if j<len(r) else '') for j in idx)
            rr=sorted(rows,key=key,reverse=('-R' in a or '--reverse' in a))
        out(([head] if head else [])+rr,d,dest);return 0
    if cmd=='search':
        pat=a[0] if a else ''; flags=re.I if '-i' in a or '--ignore-case' in a else 0; rg=re.compile(pat,flags); ss=next((a[i+1] for i,x in enumerate(a) if x in ('-s','--select')),None); idx=selection(ss,head) if ss else None
        rr=[r for r in rows if (any(r[j] if j<len(r) else '' and rg.search(r[j]) for j in (idx or range(len(r)))) != ('-v' in a or '--invert-match' in a))];out(([head] if head else [])+rr,d,dest);return 0
    if cmd=='frequency':
        idx=selection(next((a[i+1] for i,x in enumerate(a) if x in ('-s','--select')), '1-'+str(len(head or rows[0]))),head or rows[0]); lim=int(next((a[i+1] for i,x in enumerate(a) if x in ('-l','--limit')),10)); rr=[['field','value','count']];
        for j in idx:
            c={}
            for r in rows:
                v=r[j] if j<len(r) else ''; c[v]=c.get(v,0)+1
            it=sorted(c.items(),key=lambda x:x[1],reverse='--asc' not in a)
            if '--asc' in a:it=sorted(c.items(),key=lambda x:x[1])
            if '--no-nulls' in a:it=[x for x in it if x[0]!='']
            if lim:it=it[:lim]
            for v,n in it:rr.append([head[j] if head else str(j+1),v,str(n)])
        out(rr,d,dest);return 0
    if cmd=='stats':
        everything='--everything' in a; showmed=everything or '--median' in a; showmode=everything or '--mode' in a; showcard=everything or '--cardinality' in a
        fields=head or [str(i+1) for i in range(max(map(len,rows),default=0))]
        cols=['field','type','sum','min','max','min_length','max_length','mean','stddev']
        if showmed: cols.append('median')
        if showmode: cols.append('mode')
        if showcard: cols.append('cardinality')
        rr=[cols]
        for j,name in enumerate(fields):
            vals=[r[j] for r in rows if j<len(r) and r[j]!='']
            nums=[]
            for v in vals:
                try: nums.append(float(v))
                except: pass
            typ='Integer' if vals and len(nums)==len(vals) and all(float(x).is_integer() for x in nums) else ('Float' if vals and len(nums)==len(vals) else ('Unicode' if vals else 'NULL'))
            def fmt(x):
                if x is None:return ''
                return str(int(x)) if isinstance(x,float) and x.is_integer() else str(x)
            if vals:
                sm= sum(nums) if len(nums)==len(vals) else None
                mn=min(vals);mx=max(vals); lens=[len(x) for x in vals]
                mean=(sm/len(nums)) if sm is not None else None
                sd=math.sqrt(sum((x-mean)**2 for x in nums)/len(nums)) if mean is not None else None
                row=[name,typ,fmt(sm),mn,mx,str(min(lens)),str(max(lens)),fmt(mean),fmt(sd)]
                if showmed:row.append(fmt(statistics.median(nums)) if nums and len(nums)==len(vals) else '')
                if showmode:
                    from collections import Counter
                    cc=Counter(vals); mm=max(cc.values()); modes=[x for x,n in cc.items() if n==mm]; row.append(modes[0] if mm>1 else 'N/A')
                if showcard:row.append(str(len(set(vals))))
            else:
                row=[name,'NULL','','','','0','0','','']+([''] if showmed else [])+([''] if showmode else [])+(['0'] if showcard else [])
            rr.append(row)
        out(rr,d,dest);return 0
    if cmd=='flatten':
        sep=next((a[i+1] for i,x in enumerate(a) if x in ('-s','--separator')),'#'); names=head or [str(i+1) for i in range(len(rows[0]) if rows else 0)];
        f=sys.stdout
        for r in rows:
            for i,v in enumerate(r): f.write(f'{names[i] if i<len(names) else i+1}   {v}\n')
            f.write(sep+'\n')
        return 0
    if cmd=='table':
        rr=([head] if head else [])+rows; widths=[max([len(r[i]) if i<len(r) else 0 for r in rr]+[int(next((a[i+1] for i,x in enumerate(a) if x in ('-w','--width')),2))]) for i in range(max(map(len,rr),default=0))]; pad=int(next((a[i+1] for i,x in enumerate(a) if x in ('-p','--pad')),2));
        text='\n'.join((' '*pad).join((r[i] if i<len(r) else '').ljust(widths[i]) for i in range(len(widths))).rstrip() for r in rr)+'\n'; (open(dest,'w').write(text) if dest else sys.stdout.write(text));return 0
    if cmd in ('fmt','input'): out(([head] if head else [])+rows,next((a[i+1] for i,x in enumerate(a) if x in ('-t','--out-delimiter')),','),dest);return 0
    if cmd=='fixlengths':
        n=int(next((a[i+1] for i,x in enumerate(a) if x in ('-l','--length')),max([len(r) for r in rows]+[len(head),1])));out(([head[:n]+['']*max(0,n-len(head))] if head else [])+[r[:n]+['']*max(0,n-len(r)) for r in rows],d,dest);return 0
    if cmd=='sample':
        n=int(a[0]) if a and a[0].isdigit() else 1; random.seed(int(next((a[i+1] for i,x in enumerate(a) if x=='--seed'),0)) if '--seed' in a else None);out(([head] if head else [])+random.sample(rows,min(n,len(rows))),d,dest);return 0
    if cmd=='cat': out(([head] if head else [])+rows,d,dest);return 0
    if cmd in ('index','split','partition'): return 0
    out(([head] if head else [])+rows,d,dest);return 0
if __name__=='__main__':sys.exit(main(sys.argv[1:]))
